import{_ as e,c as o,o as a,a4 as i}from"./chunks/framework.BgUgRheH.js";const p=JSON.parse('{"title":"Migration Guide","description":"","frontmatter":{},"headers":[],"relativePath":"migrating.md","filePath":"migrating.md","lastUpdated":1634990939000}'),t={name:"migrating.md"},s=i('<h1 id="migration-guide" tabindex="-1">Migration Guide <a class="header-anchor" href="#migration-guide" aria-label="Permalink to &quot;Migration Guide&quot;">​</a></h1><h2 id="from-2-x-to-3-x" tabindex="-1">From 2.x to 3.x <a class="header-anchor" href="#from-2-x-to-3-x" aria-label="Permalink to &quot;From 2.x to 3.x&quot;">​</a></h2><h3 id="breaking-changes" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h3><ul><li><p><strong>Defining abilities without a subject is not allowed anymore.</strong> For example, <code>can :dashboard</code> is not going to be accepted anymore and will raise an exception. All these kind of rules need to be rethought in terms of <code>can action, subject</code>. <code>can :read, :dashboard</code> for example.</p></li><li><p><strong>Eager loading is not automatic.</strong> If you relied on CanCanCan to avoid N+1 queries, this will not be the case anymore. From now on, all necessary <code>includes</code>, <code>preload</code> or <code>eager_load</code> need to be explicitly written. We strongly suggest to have <code>bullet</code> gem installed to identify your possible N+1 issues.</p></li><li><p><strong>Use of distinct.</strong> Uniqueness of the results is guaranteed by using the <code>distinct</code> clause in the final query. This may cause issues with some existing queries when using clauses like <code>group by</code> or <code>order</code> on associations. Adding a custom <code>select</code> may be necessary in these cases.</p></li><li><p><strong>aliases are now merged.</strong> When using the method to merge different Ability files, the aliases are now also merged. This might cause some incompatibility issues.</p></li></ul>',4),n=[s];function r(d,c,l,g,h,u){return a(),o("div",null,n)}const _=e(t,[["render",r]]);export{p as __pageData,_ as default};
